        {
         "t": "脊髓位于椎管内，上端在**枕大孔**与延髓相连，下端形成**脊髓圆锥**，圆锥以下为无神经组织的**终丝**；三层被膜内→外为**软膜、蛛网膜、硬膜**。",
         "s": "彭国平·脊髓概述 p4"
        },
        {
         "t": "下端终于 **L1–2**，故腰椎穿刺取 **L3–5**；颈膨大 **C5–T2**、腰膨大 **L1–S2** 分别发出上、下肢神经根。",
         "s": "p2、p4"
        },
        {
         "t": "**前角**为运动细胞；**侧角** C8–L2 为**交感节前神经元**（C8–T1 损害见 **Horner 征**）；**后角**接痛温触觉一级纤维。",
         "s": "p7"
        },
        {
         "t": "**侧索**：下行 **皮质脊髓侧束**、上行 **脊髓丘脑侧束**（痛温觉纤维**由外向内为骶、腰、胸、颈**）；**前索** = 未交叉的**皮质脊髓前束**。",
         "s": "p8"
        },
        {
         "t": "**后索** = **薄束、楔束**；楔束在薄束外侧，**薄束传 T4 以下、楔束传 T4 以上**同侧本体觉与精细触觉；起自同侧脊神经节，止于薄束核、楔束核。",
         "s": "p8"
        }
