         "t": "感觉与自主神经障碍：病变节段以下**所有感觉缺失或下降**，缺失上缘可有感觉过敏区或束带状感觉异常；**大小便潴留、失禁**（逼尿肌松弛→无张力性神经原性膀胱→充盈性尿失禁；逼尿肌痉挛→痉挛性小膀胱）。",
