         "t": "概念与分型：运动神经元病是病因未明、主要累及大脑皮质、脑干和脊髓运动神经元的变性疾病，分 ALS、进行性肌萎缩（PMA）、进行性延髓麻痹（PBP）、原发性侧索硬化（PLS）四型；**ALS 最常见**，为致死性神经系统退行性病，**上下运动神经元同时受损**，10% 有家族性。",
         "s": "彭国平·ALS p5–p6"
