         "t": "概念与发病机制：结核性脑膜炎（TBM）是结核分枝杆菌引起的脑膜**非化脓性**炎症，占中枢神经系统结核病的 **70%**；常为**全身性粟粒性结核病的一部分，经血行播散**而来，亦可由脑实质或脑膜结核病灶溃破进入蛛网膜下腔及脑脊液，偶见脊椎、颅骨或中耳乳突病灶直接蔓延。",
