         "t": "临床分期（亚急性病程，三期）：**早期（前驱期）约 1~3 周**——精神性格改变（少言、懒动、易倦、烦躁、易怒）、发热、盗汗、消瘦；**中期（脑膜刺激期）约 1~2 周**——颅内压增高致剧烈头痛、喷射性呕吐、明显脑膜刺激征，脑神经障碍**最常见面神经瘫痪**，其次动眼神经和展神经，眼底可见**脉络膜粟粒状结核结节**；**晚期（昏迷期）约 1~3 周**——意识朦胧至昏迷，惊厥频繁，最终脑疝致死。",
