         "t": "强化机制与**血脑屏障（BBB）**：CNS 对比增强＝**血管内增强**（反映新生血管、扩张或充血）＋**间质（血管外）增强**（取决于 BBB）。**颅骨、硬脑膜（大脑镰、小脑幕）无 BBB**；肿瘤、梗死、感染破坏 BBB 使紧密连接开放，对比剂进入脑组织而强化。",
